<?php
require_once __DIR__.'/lib/auth.php';requireAuth();require_once __DIR__.'/lib/workspace.php';$pdo=db();
$stats=$pdo->query("SELECT COUNT(*) resumes,SUM(stage='Interview') interviews,SUM(stage='Offer') offers,SUM(COALESCE(country_code,country_name,'')='') missing_country FROM candidates")->fetch();$jobTotal=(int)$pdo->query("SELECT COUNT(*) FROM jobs WHERE status IN ('open','draft')")->fetchColumn();$selectedTotal=(int)$pdo->query("SELECT COUNT(*) FROM wishlist_items WHERE disposition='selected'")->fetchColumn();
$jobs=$pdo->query("SELECT j.*,COUNT(DISTINCT c.id) applicants,COUNT(DISTINCT CASE WHEN wi.disposition='wishlist' THEN wi.candidate_id END) shortlisted,COUNT(DISTINCT CASE WHEN wi.disposition='selected' THEN wi.candidate_id END) selected,wp.id profile_id FROM jobs j LEFT JOIN candidates c ON c.job_id=j.id LEFT JOIN wishlist_profiles wp ON wp.job_id=j.id LEFT JOIN wishlist_items wi ON wi.profile_id=wp.id GROUP BY j.id,wp.id ORDER BY FIELD(j.status,'open','draft','paused','closed'),j.created_at DESC")->fetchAll();
$countries=$pdo->query("SELECT country_code,country_name,COUNT(*) total FROM candidates WHERE COALESCE(country_code,country_name,'')<>'' GROUP BY country_code,country_name ORDER BY total DESC")->fetchAll();foreach($countries as &$country)$country['country_code']=countryCodeFromName($country['country_code'],$country['country_name']);unset($country);$maxCountry=max(array_column($countries,'total')?:[1]);$sources=$pdo->query('SELECT source_name,COUNT(*) total FROM candidates GROUP BY source_name ORDER BY total DESC')->fetchAll();$stageRows=$pdo->query('SELECT stage,COUNT(*) total FROM candidates GROUP BY stage')->fetchAll();$stageMap=[];foreach($stageRows as $r)$stageMap[$r['stage']]=$r['total'];
$activePage='dashboard';$pageTitle='Dashboard · ResumeIQ';$pageStyles='<style>.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.metric{padding:16px}.metric strong{font-size:23px;display:block}.metric span{font-size:9px;color:var(--muted)}.dash{display:grid;grid-template-columns:1fr 330px;gap:10px;margin-top:10px}.box{padding:17px}.title{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.jobs{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.job{padding:15px;border:1px solid var(--line);border-radius:10px}.job h3{margin:0 0 5px;font-size:14px}.job p{font-size:9px;color:var(--muted);min-height:30px}.job-meta,.actions{display:flex;gap:7px;flex-wrap:wrap}.job-meta{font-size:9px;margin:10px 0}.actions .btn{height:31px;padding:0 9px}.world{padding:10px;background:#fafafe;border:1px solid var(--line)}.world-map{width:100%;height:180px}.world-map path{fill:#e2def6;stroke:#fff;stroke-width:.35}.world-map path.has-data{fill:var(--primary);cursor:pointer}.country{display:flex;justify-content:space-between;padding:6px 0;font-size:9px;border-bottom:1px solid var(--line)}.funnel{display:grid;grid-template-columns:repeat(5,1fr);gap:5px}.funnel div{text-align:center;padding:8px;background:#fafafe}.funnel strong{display:block}@media(max-width:950px){.dash{grid-template-columns:1fr}.metric-grid,.jobs{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.metric-grid,.jobs{grid-template-columns:1fr}}</style>';require __DIR__.'/views/partials/header.php';?>
<section class="metric-grid"><a class="panel metric" href="candidates.php"><strong><?=(int)$stats['resumes']?></strong><span>Resumes with candidate records</span></a><a class="panel metric" href="#jobs"><strong><?=$jobTotal?></strong><span>Open + draft jobs</span></a><a class="panel metric" href="wishlist.php"><strong><?=$selectedTotal?></strong><span>Recruiter selected</span></a><a class="panel metric" href="pipeline.php"><strong><?=(int)$stats['interviews']?> + <?=(int)$stats['offers']?></strong><span>Interview + offer</span></a></section>
<section class="dash"><main><article class="panel box" id="jobs"><div class="title"><div><h2>Open jobs</h2><small>Job configuration, applicants and hiring workflow in one place.</small></div><a class="btn btn-primary" href="job_edit.php"><i class="fa-solid fa-plus"></i>Create job</a></div><div class="jobs"><?php foreach($jobs as $job):$description=trim(preg_replace('/\s+/',' ',html_entity_decode(strip_tags($job['description']),ENT_QUOTES|ENT_HTML5,'UTF-8')));?><article class="job"><h3><?=htmlspecialchars(trim($job['title']))?></h3><p><?=htmlspecialchars(mb_strimwidth($description,0,125,'…'))?></p><div class="job-meta"><span class="tag"><?=(int)$job['applicants']?> applicants</span><span class="tag"><?=(int)$job['shortlisted']?> wishlist</span><span class="tag"><?=(int)$job['selected']?> selected</span><span class="tag"><?=htmlspecialchars($job['status'])?></span><?php if($job['min_experience']!==null||$job['max_experience']!==null):?><span class="tag"><?=htmlspecialchars(($job['min_experience']??'0').'–'.($job['max_experience']??'∞'))?>y</span><?php endif?></div><div class="actions"><?php if($job['profile_id']):?><a class="btn" href="job_profile.php?id=<?=$job['profile_id']?>">Top 5</a><a class="btn" href="wishlist.php?profile=<?=$job['profile_id']?>">Wishlist</a><?php endif?><a class="btn" href="pipeline.php?job_id=<?=$job['id']?>">Pipeline</a><a class="btn" href="job_edit.php?id=<?=$job['id']?>">Edit</a><?php if($job['public_url']):?><a class="btn" target="_blank" rel="noopener" href="<?=htmlspecialchars($job['public_url'])?>">Public job <i class="fa-solid fa-arrow-up-right-from-square"></i></a><?php endif?></div></article><?php endforeach?></div></article><article class="panel box" style="margin-top:10px"><div class="title"><h2>Hiring funnel</h2><a href="pipeline.php">All candidates</a></div><div class="funnel"><?php foreach(['Applied','Screening','Interview','Offer','Rejected'] as $stage):?><div><strong><?=$stageMap[$stage]??0?></strong><small><?=$stage?></small></div><?php endforeach?></div></article></main>
<aside><article class="panel box"><div class="title"><h2>Candidate locations</h2><span class="tag"><?=count($countries)?> countries</span></div><div class="world" id="world"></div><?php foreach($countries as $country):?><a class="country" href="candidates.php?country=<?=urlencode($country['country_code'])?>"><span><?=htmlspecialchars($country['country_name']?:$country['country_code'])?></span><b><?=$country['total']?> · <?=round($country['total']/max(1,$stats['resumes'])*100)?>%</b></a><?php endforeach?></article><article class="panel box" style="margin-top:10px"><div class="title"><h2>Resume sources</h2><a href="sources.php">Manage</a></div><?php foreach($sources as $source):?><div class="country"><span><?=htmlspecialchars($source['source_name'])?></span><b><?=$source['total']?></b></div><?php endforeach?></article></aside></section>
<script>const data=<?=json_encode(array_column($countries,null,'country_code'),JSON_HEX_TAG|JSON_HEX_AMP)?>;fetch('assets/world.svg').then(r=>r.text()).then(t=>{const svg=new DOMParser().parseFromString(t,'image/svg+xml').documentElement;svg.classList.add('world-map');Object.entries(data).forEach(([code,c])=>{const p=svg.querySelector('#'+CSS.escape(code));if(!p)return;p.classList.add('has-data');const title=document.createElementNS('http://www.w3.org/2000/svg','title');title.textContent=(c.country_name||code)+': '+c.total+' resumes ('+Math.round(c.total/<?=max(1,(int)$stats['resumes'])?>*100)+'%)';p.appendChild(title);p.setAttribute('data-country',code)});document.getElementById('world').appendChild(document.importNode(svg,true));document.querySelectorAll('.world-map path.has-data').forEach(p=>p.onclick=()=>location.href='candidates.php?country='+encodeURIComponent(p.dataset.country))});</script>
